window.TDL={formEndpoint:"https://formspree.io/f/myewdzeo",reviewsEndpoint:"https://script.google.com/macros/s/AKfycbxigQJk7zmJWIviGcniXVpsPEtTJvBwLXplTKntfo3kk07REx2H2oV76d6xI7vLPrp_TA/exec"};
