function clean(a){var o=[];if(Array.isArray(a))a.forEach(function(x){if(!x)return;var txt=typeof x.text==='string'?x.text.trim().slice(0,1000):'';var r=Math.round(Number(x.rating));if(!txt||!(r>=1&&r<=5))return;o.push({t:txt,n:typeof x.name==='string'?x.name.trim().slice(0,60):'',r:r})});return o}
