function tdlSend(subject,fields,mailBody,ok,fail){
 var ep=(window.TDL&&TDL.formEndpoint)||'';
 if(!ep){location.href='mailto:admin@thedesignloft.ae?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(mailBody);return}
 fields._subject=subject;
 fetch(ep,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(fields)})
  .then(function(r){if(!r.ok)throw 0;ok()}).catch(fail)}
(function(){
var f=document.getElementById('fbf'),note=document.getElementById('fbn'),btn=f.querySelector('.fbb'),busy=false;
if(window.TDL&&TDL.reviewsEndpoint)note.textContent='Your feedback will appear under \u201CThe Client Perspective\u201D above.';else if(window.TDL&&TDL.formEndpoint)note.textContent='Thank you for sharing. Approved feedback will appear under \u201CThe Client Perspective\u201D.';
f.addEventListener('submit',function(ev){
 ev.preventDefault();if(busy)return;
 var c=f.querySelector('input[name=r]:checked'),name=f.n.value.trim().slice(0,60),msg=f.m.value.trim().slice(0,1000);
 if(!msg||!c)return;
 var rep=window.TDL&&TDL.reviewsEndpoint;
 if(rep){
  busy=true;btn.disabled=true;note.textContent='Sending\u2026';
  fetch(rep,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({name:name,rating:Number(c.value),text:msg,website:f.website.value})}).then(function(){
   if(!f.website.value&&window.tdlAddReview)window.tdlAddReview({t:msg,n:name,r:Number(c.value)});
   f.reset();note.textContent='Thank you! Your feedback is now shown under \u201CThe Client Perspective\u201D.';
   var rv=document.getElementById('reviews');if(rv)rv.scrollIntoView({behavior:'smooth',block:'start'})
  }).catch(function(){note.textContent='We could not post your feedback just now. Please try again in a moment.'}).then(function(){busy=false;btn.disabled=false});
  return}
 name=name||'Anonymous';
 busy=true;btn.disabled=true;
 tdlSend('Client feedback',{name:name,rating:c.value+' / 5',message:msg},'Name: '+name+'\nRating: '+c.value+' / 5\n\n'+msg,
  function(){f.reset();note.textContent='Thank you! Your feedback has been received and will appear once approved.';busy=false;btn.disabled=false},
  function(){note.textContent='We could not send your feedback just now. Please try again, or email admin@thedesignloft.ae.';busy=false;btn.disabled=false});
 if(!(window.TDL&&TDL.formEndpoint)){busy=false;btn.disabled=false}
});
})();
